def get_menu():
    """Return a de-duplicated list of (name, category, price) tuples."""
    seen, result = set(), []
    for category, items in MENU.items():
        for name, price in items:
            if name.lower() not in seen:
                seen.add(name.lower())
                result.append((name, category, price))
    return result


