# ----------------------------------------------------------------- database
class DB:
    def __init__(self, path=DB_FILE):
        self.conn = sqlite3.connect(path)
        self.conn.execute("PRAGMA foreign_keys = ON")
        self.create_tables()
        self.seed()

    def q(self, sql, args=()):
        return self.conn.execute(sql, args).fetchall()

    def one(self, sql, args=()):
        row = self.conn.execute(sql, args).fetchone()
        return row

    def x(self, sql, args=()):
        cur = self.conn.execute(sql, args)
        self.conn.commit()
        return cur.lastrowid

    def create_tables(self):
        self.conn.executescript("""
        CREATE TABLE IF NOT EXISTS menu(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE NOT NULL,
            category TEXT NOT NULL,
            price REAL NOT NULL,
            available INTEGER NOT NULL DEFAULT 1);
        CREATE TABLE IF NOT EXISTS tables(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            number INTEGER UNIQUE NOT NULL,
            capacity INTEGER NOT NULL,
            status TEXT NOT NULL DEFAULT 'Free');
        CREATE TABLE IF NOT EXISTS orders(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            table_id INTEGER REFERENCES tables(id),
            order_type TEXT NOT NULL DEFAULT 'Dine-In',
            status TEXT NOT NULL DEFAULT 'Placed',
            created TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS order_items(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
            name TEXT NOT NULL,
            price REAL NOT NULL,
            qty INTEGER NOT NULL);
        CREATE TABLE IF NOT EXISTS bills(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_id INTEGER NOT NULL,
            table_number INTEGER,
            customer TEXT,
            subtotal REAL, discount REAL, gst REAL, total REAL,
            mode TEXT, created TEXT);
        CREATE TABLE IF NOT EXISTS reviews(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            customer TEXT, rating INTEGER, comment TEXT, created TEXT);
        """)
        self.migrate_for_takeaway()
        self.conn.commit()

    def migrate_for_takeaway(self):
        # Upgrade databases created by the previous version so Take Away orders
        # can be stored without requiring a table.
        order_cols = {r[1]: r for r in self.conn.execute("PRAGMA table_info(orders)").fetchall()}
        if order_cols and (order_cols["table_id"][3] == 1 or "order_type" not in order_cols):
            self.conn.execute("PRAGMA foreign_keys=OFF")
            self.conn.execute("ALTER TABLE orders RENAME TO orders_old")
            self.conn.execute("""CREATE TABLE orders(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                table_id INTEGER REFERENCES tables(id),
                order_type TEXT NOT NULL DEFAULT 'Dine-In',
                status TEXT NOT NULL DEFAULT 'Placed',
                created TEXT NOT NULL)""")
            if "order_type" in order_cols:
                self.conn.execute("INSERT INTO orders(id, table_id, order_type, status, created) SELECT id, table_id, order_type, status, created FROM orders_old")
            else:
                self.conn.execute("INSERT INTO orders(id, table_id, order_type, status, created) SELECT id, table_id, 'Dine-In', status, created FROM orders_old")
            # Rebuild order_items as well because SQLite updates its foreign-key
            # target when orders is renamed during the migration.
            self.conn.execute("ALTER TABLE order_items RENAME TO order_items_old")
            self.conn.execute("""CREATE TABLE order_items(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
                name TEXT NOT NULL,
                price REAL NOT NULL,
                qty INTEGER NOT NULL)""")
            self.conn.execute("INSERT INTO order_items(id, order_id, name, price, qty) SELECT id, order_id, name, price, qty FROM order_items_old")
            self.conn.execute("DROP TABLE order_items_old")
            self.conn.execute("DROP TABLE orders_old")

            bill_cols = {r[1]: r for r in self.conn.execute("PRAGMA table_info(bills)").fetchall()}
            if bill_cols and bill_cols["table_number"][3] == 1:
                self.conn.execute("ALTER TABLE bills RENAME TO bills_old")
                self.conn.execute("""CREATE TABLE bills(
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    order_id INTEGER NOT NULL,
                    table_number INTEGER,
                    customer TEXT,
                    subtotal REAL, discount REAL, gst REAL, total REAL,
                    mode TEXT, created TEXT)""")
                self.conn.execute("INSERT INTO bills SELECT id, order_id, table_number, customer, subtotal, discount, gst, total, mode, created FROM bills_old")
                self.conn.execute("DROP TABLE bills_old")
            self.conn.execute("PRAGMA foreign_keys=ON")
        elif order_cols and "order_type" not in order_cols:
            self.conn.execute("ALTER TABLE orders ADD COLUMN order_type TEXT NOT NULL DEFAULT 'Dine-In'")

    def seed(self):
        if self.one("SELECT COUNT(*) FROM menu")[0] == 0:
            self.conn.executemany(
                "INSERT OR IGNORE INTO menu(name, category, price) VALUES (?,?,?)",
                get_menu())
        if self.one("SELECT COUNT(*) FROM tables")[0] == 0:
            caps = [2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 8]
            self.conn.executemany(
                "INSERT INTO tables(number, capacity) VALUES (?,?)",
                [(i + 1, c) for i, c in enumerate(caps)])
        self.conn.commit()

    # ---- helpers used by several windows
    def open_order(self, table_id):
        r = self.one("SELECT id FROM orders WHERE table_id=? AND status IN "
                     "('Placed','Preparing','Served')", (table_id,))
        return r[0] if r else None

    def order_total(self, order_id):
        r = self.one("SELECT COALESCE(SUM(price*qty),0) FROM order_items "
                     "WHERE order_id=?", (order_id,))
        return r[0]

    def release_table(self, table_id):
        if not self.open_order(table_id):
            self.x("UPDATE tables SET status='Free' WHERE id=?", (table_id,))


# ----------------------------------------------------------------- base popup
class Popup(tk.Toplevel):
    def __init__(self, app, title, size):
        super().__init__(app.root)
        self.app, self.db = app, app.db
        self.title(title)
        self.geometry(size)
        self.configure(bg=BG)
        self.protocol("WM_DELETE_WINDOW", self.close)
        tk.Label(self, text=title, bg=PRIMARY, fg="white",
                 font=("Segoe UI", 15, "bold"), pady=8).pack(fill="x")

    def close(self):
        self.app.windows.pop(type(self), None)
        self.destroy()

    def refresh(self):
        pass

    @staticmethod
    def make_tree(parent, cols, widths, height=12):
        frame = tk.Frame(parent)
        tree = ttk.Treeview(frame, columns=cols, show="headings", height=height)
        for c, w in zip(cols, widths):
            tree.heading(c, text=c)
            tree.column(c, width=w, anchor="w" if w > 90 else "center")
        sb = ttk.Scrollbar(frame, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=sb.set)
        tree.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")
        return frame, tree


def menu_filter_sql(search, category, only_available=False):
    sql, args = "SELECT id, name, category, price, available FROM menu WHERE 1=1", []
    if search:
        sql += " AND name LIKE ?"
        args.append(f"%{search}%")
    if category and category != "All":
        sql += " AND category=?"
        args.append(category)
    if only_available:
        sql += " AND available=1"
    return sql + " ORDER BY category, name", args


